+import { describe, expect, test } from "bun:test";
+import { LlmStreamError } from "../../../../../../src/orchestration/agent-runtime/llm/errors.js";
+import type { AgentRows, SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+import type { HostStepItem } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/host-gate.js";
+
+const SERVICE_FAILURE = new Error("529 overloaded");
+const THOUGHT: SignedBlock = { type: "thinking", thinking: "plan", signature: "sig-1" };
+const STOP: HostStepItem = { kind: "stop", stopReason: "end_turn", usage: null };
+
+/** A step whose engine writes `written` to the agent file only once the stream has read `after` events: an engine
+ *  that writes a block's row when the response ends, not when the block does. */
+function step(script: readonly StepEvent[], written: readonly SignedBlock[], after: number) {
+  let taken = 0;
+  const rows: AgentRows = { read: () => taken >= after ? written : [] };
+  /** @yields {StepEvent} Each event of the script, then nothing more: the engine went quiet. */
+  async function* events(): AsyncGenerator<StepEvent> {
+    for (const event of script) {
+      taken += 1;
+      yield event;
+    }
+    await new Promise<never>(() => {});
+  }
+  return { rows, events: events() };
+}
+
+const items = (...list: HostStepItem[]): StepEvent[] => list.map((item) => ({ kind: "item", item }));
+
+async function collect(script: readonly StepEvent[], written: readonly SignedBlock[], after: number) {
+  const { rows, events } = step(script, written, after);
+  const answers: HostedAnswer[] = [];
+  let progress = 0;
+  const seen: string[] = [];
+  for await (const event of hostedStreamEvents(events, rows, 0, "model", async () => SERVICE_FAILURE, (answer) => { answers.push(answer); }, () => { progress += 1; })) {
+    if (event.type === "content_block_delta") seen.push(`${event.index}:${event.delta.type}`);
+    else if (event.type === "content_block_start" || event.type === "content_block_stop") seen.push(`${event.index}:${event.type}`);
+    else seen.push(event.type);
+  }
+  return { seen, answers, progress };
+}
+
+describe("the hosted stream", () => {
+  test("holds back the chunks after a thinking block until the engine writes its row at the response's end, reports each as progress, and streams the response in Anthropic order", async () => {
+    const script = items(
+      { kind: "thinking", index: 0, text: "plan" },
+      { kind: "text", index: 1, text: "Hello" },
+      { kind: "text", index: 1, text: " world" },
+      STOP,
+    );
+
+    const { seen, answers, progress } = await collect(script, [THOUGHT], script.length);
+
+    expect(seen).toEqual([
+      "message_start",
+      "0:content_block_start", "0:thinking_delta", "0:signature_delta", "0:content_block_stop",
+      "1:content_block_start", "1:text_delta", "1:text_delta", "1:content_block_stop",
+      "message_delta", "message_stop",
+    ]);
+    // The second text chunk and the stop chunk: the first text chunk is the one whose arrival began the wait.
+    expect(progress).toBe(2);
+    expect(answers).toEqual([{ message: { role: "assistant", content: [THOUGHT, { type: "text", text: "Hello world" }] }, stopReason: "end_turn" }]);
+  });
+
+  test("takes a redacted thinking block's data from a row that the engine writes after the chunks of the next block", async () => {
+    const redacted: SignedBlock = { type: "redacted_thinking", data: "opaque" };
+    const script = items({ kind: "text", index: 1, text: "Hi" }, STOP);
+
+    const { seen, answers } = await collect(script, [redacted], script.length);
+
+    expect(seen).toEqual(["message_start", "0:content_block_start", "0:content_block_stop", "1:content_block_start", "1:text_delta", "1:content_block_stop", "message_delta", "message_stop"]);
+    expect(answers[0]?.message.content[0]).toEqual(redacted);
+  });
+
+  test("fails with the service's answer when the step ends without a stop chunk while a row is missing", async () => {
+    const script: StepEvent[] = [...items({ kind: "thinking", index: 0, text: "plan" }, { kind: "text", index: 1, text: "Hel" }), { kind: "done" }];
+
+    await expect(collect(script, [], 0)).rejects.toBe(SERVICE_FAILURE);
+  });
+
+  test("fails transient when a signed block's row is still missing after the stop chunk", async () => {
+    const script = items({ kind: "thinking", index: 0, text: "plan" }, { kind: "text", index: 1, text: "Hello" }, STOP);
+
+    const failure = await collect(script, [], 0).catch((error: unknown) => error);
+
+    expect(failure).toBeInstanceOf(LlmStreamError);
+    expect(failure).toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row for a signed block") });
+  }, 15_000);
+});

