@@ -0,0 +1,72 @@
+import { describe, expect, setSystemTime, test } from "bun:test";
+import type Anthropic from "@anthropic-ai/sdk";
+import { LlmStreamError } from "../../../../../../src/orchestration/agent-runtime/llm/errors.js";
+import type { SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+
+const SIGNED: SignedBlock = { type: "thinking", thinking: "plan", signature: "sig" };
+const STOP: StepEvent = { kind: "item", item: { kind: "stop", stopReason: "end_turn", usage: null } };
+const SERVICE_FAILURE = new Error("overloaded");
+
+/** The events of one hosted step, whose engine writes the thinking block's row only when the stream reaches `rowAt`.
+ *  The model writes for 30 seconds after it thinks. */
+function slowStep(rowAt: number, rows: SignedBlock[], tail: readonly StepEvent[]) {
+  const events: StepEvent[] = [
+    { kind: "item", item: { kind: "thinking", index: 0, text: "plan" } },
+    { kind: "item", item: { kind: "text", index: 1, text: "a" } },
+    { kind: "item", item: { kind: "text", index: 1, text: "b" } },
+    ...tail,
+  ];
+  return (async function* (): AsyncGenerator<StepEvent> {
+    for (const [at, event] of events.entries()) {
+      if (at === rowAt) rows.push(SIGNED);
+      if (at === 2) setSystemTime(new Date(Date.now() + 30_000));
+      yield event;
+    }
+  })();
+}
+
+async function run(events: AsyncIterable<StepEvent>, rows: SignedBlock[], read: () => readonly SignedBlock[] = () => rows) {
+  const streamed: Anthropic.RawMessageStreamEvent[] = [];
+  let progress = 0;
+  try {
+    for await (const event of hostedStreamEvents(events, { read }, 0, "model", async () => SERVICE_FAILURE, () => {}, () => { progress += 1; })) streamed.push(event);
+    return { streamed, progress, error: undefined };
+  } catch (error) {
+    return { streamed, progress, error };
+  } finally {
+    setSystemTime();
+  }
+}
+
+describe("hostedStreamEvents", () => {
+  test("a response that writes long after its thinking completes in Anthropic order, reporting each held chunk as progress", async () => {
+    const rows: SignedBlock[] = [];
+    const { streamed, progress, error } = await run(slowStep(3, rows, [STOP]), rows);
+    expect(error).toBeUndefined();
+    expect(streamed.map((event) => event.type === "content_block_delta" ? event.delta.type : event.type)).toEqual([
+      "message_start", "content_block_start", "thinking_delta", "signature_delta", "content_block_stop",
+      "content_block_start", "text_delta", "text_delta", "content_block_stop", "message_delta", "message_stop",
+    ]);
+    expect(streamed.find((event) => event.type === "content_block_delta" && event.delta.type === "signature_delta")).toMatchObject({ index: 0, delta: { signature: "sig" } });
+    // The second text chunk and the stop chunk arrived while the stream held them for the row.
+    expect(progress).toBe(2);
+  });
+
+  test("a signed row still missing after the stop chunk fails transient with wrote no row", async () => {
+    const rows: SignedBlock[] = [];
+    // Each read of the agent file takes a second of the clock, so the bound passes at once.
+    const { error } = await run(slowStep(-1, rows, [STOP]), rows, () => {
+      setSystemTime(new Date(Date.now() + 1_000));
+      return rows;
+    });
+    expect(error).toBeInstanceOf(LlmStreamError);
+    expect(error).toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row") });
+  });
+
+  test("a step that ends without a stop chunk while a row is pending fails with the service's answer", async () => {
+    const rows: SignedBlock[] = [];
+    const { error } = await run(slowStep(-1, rows, [{ kind: "done" }]), rows);
+    expect(error).toBe(SERVICE_FAILURE);
+  });
+});

