+import { afterEach, describe, expect, setSystemTime, test } from "bun:test";
+import type Anthropic from "@anthropic-ai/sdk";
+import { appendFileSync, writeFileSync } from "node:fs";
+import { join } from "node:path";
+import { LlmStreamError } from "../../../../../../src/orchestration/agent-runtime/llm/errors.js";
+import type { CliBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/cli-view.js";
+import { agentRows, type SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+import type { HostStepItem } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/host-gate.js";
+import { temporaryDirectories } from "../../../../../helpers/directories.js";
+
+const temporaryDirectory = temporaryDirectories();
+afterEach(() => { setSystemTime(); });
+
+const THINKING: SignedBlock = { type: "thinking", thinking: "Plan the answer.", signature: "sig-1" };
+const REDACTED: SignedBlock = { type: "redacted_thinking", data: "opaque" };
+const STOP: HostStepItem = { kind: "stop", stopReason: "end_turn", usage: { input_tokens: 3, output_tokens: 5, cache_read_input_tokens: 0, cache_creation_input_tokens: 0 } };
+const SERVICE_ANSWER = new Error("529 overloaded");
+
+/** An agent file that the engine appends its rows to, and the stream's reader of it. */
+function agentFile() {
+  const path = join(temporaryDirectory("agent-stream-"), "agent.jsonl");
+  writeFileSync(path, "");
+  return {
+    rows: agentRows(path, 0),
+    write: (...blocks: SignedBlock[]) => {
+      for (const block of blocks) appendFileSync(path, `${JSON.stringify({ type: "assistant", message: { role: "assistant", content: [block] } })}\n`);
+    },
+  };
+}
+
+/** The step's chunks as the host gate hands them on; `beforeLast` runs before the last chunk goes out.
+ *  @yields {StepEvent} Each chunk, then the step's end. */
+async function* step(items: readonly HostStepItem[], beforeLast: () => void = () => {}): AsyncGenerator<StepEvent> {
+  for (const [at, item] of items.entries()) {
+    if (at === items.length - 1) beforeLast();
+    yield { kind: "item", item };
+  }
+  yield { kind: "done" };
+}
+
+/** Runs the stream to its end and returns what it yielded, the error that ended it, the answer, and the progress
+ *  reports. `onProgress` also runs on each report. */
+async function run(events: AsyncIterable<StepEvent>, rows: ReturnType<typeof agentFile>["rows"], onProgress: () => void = () => {}) {
+  const yielded: Anthropic.RawMessageStreamEvent[] = [];
+  let answer: HostedAnswer | undefined;
+  let progress = 0;
+  let error: unknown;
+  try {
+    for await (const event of hostedStreamEvents(events, rows, 0, "claude-test", async () => SERVICE_ANSWER, (value) => { answer = value; }, () => { progress += 1; onProgress(); })) yielded.push(event);
+  } catch (caught) {
+    error = caught;
+  }
+  return { yielded, answer, progress, error };
+}
+
+/** Each event as its type, its block index, and the kind of its block or delta. */
+const shape = (events: readonly Anthropic.RawMessageStreamEvent[]) => events.map((event) => {
+  if (event.type === "content_block_start") return `start ${event.index} ${event.content_block.type}`;
+  if (event.type === "content_block_delta") return `delta ${event.index} ${event.delta.type}`;
+  if (event.type === "content_block_stop") return `stop ${event.index}`;
+  return event.type;
+});
+
+describe("the hosted agent's stream", () => {
+  test("a response that writes long after its thinking completes in Anthropic order, with the rows the engine writes at its end, and reports each chunk that it holds as progress", async () => {
+    const file = agentFile();
+    // The engine writes a signed block's row no sooner than the row of the block after it.
+    const events = step([
+      { kind: "thinking", index: 0, text: "Plan" },
+      { kind: "thinking", index: 0, text: " the" },
+      { kind: "text", index: 2, text: "Hello" },
+      { kind: "text", index: 2, text: " world" },
+      STOP,
+    ], () => { file.write(THINKING, REDACTED); });
+
+    const { yielded, answer, progress, error } = await run(events, file.rows);
+
+    expect(error).toBeUndefined();
+    expect(shape(yielded)).toEqual([
+      "message_start",
+      "start 0 thinking", "delta 0 thinking_delta", "delta 0 thinking_delta", "delta 0 thinking_delta", "delta 0 signature_delta", "stop 0",
+      "start 1 redacted_thinking", "stop 1",
+      "start 2 text", "delta 2 text_delta", "delta 2 text_delta", "stop 2",
+      "message_delta", "message_stop",
+    ]);
+    expect(yielded[4]).toEqual({ type: "content_block_delta", index: 0, delta: { type: "thinking_delta", thinking: " answer." } });
+    expect(yielded[5]).toEqual({ type: "content_block_delta", index: 0, delta: { type: "signature_delta", signature: "sig-1" } });
+    expect(yielded[7]).toEqual({ type: "content_block_start", index: 1, content_block: { type: "redacted_thinking", data: "opaque" } });
+    const content: CliBlock[] = [THINKING, REDACTED, { type: "text", text: "Hello world" }];
+    expect(answer).toEqual({ message: { role: "assistant", content }, stopReason: "end_turn" });
+    // The two text chunks arrived while the thinking block's row was pending, so the adapter heard neither.
+    expect(progress).toBe(2);
+  });
+
+  test("a signed row that is still missing after the stop chunk fails transient, reporting progress while it waits", async () => {
+    const file = agentFile();
+    let stopped = false;
+    const events = step([{ kind: "thinking", index: 0, text: "Plan" }, STOP], () => { stopped = true; });
+
+    // Each report after the stop chunk moves the clock past the wait's bound.
+    const { yielded, progress, error } = await run(events, file.rows, () => { if (stopped) setSystemTime(new Date(Date.now() + 3_600_000)); });
+
+    expect(error).toBeInstanceOf(LlmStreamError);
+    expect(error).toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row") });
+    expect(progress).toBeGreaterThan(0);
+    expect(shape(yielded)).toEqual(["message_start", "start 0 thinking", "delta 0 thinking_delta"]);
+  });
+
+  test("a step that ends without a stop chunk while a row is pending fails with the service's answer", async () => {
+    const file = agentFile();
+    const events = step([{ kind: "thinking", index: 0, text: "Plan" }, { kind: "text", index: 1, text: "Hello" }]);
+
+    const { yielded, answer, error } = await run(events, file.rows);
+
+    expect(error).toBe(SERVICE_ANSWER);
+    expect(answer).toBeUndefined();
+    expect(shape(yielded)).toEqual(["message_start", "start 0 thinking", "delta 0 thinking_delta"]);
+  });
+});

