+
+const item = (value: HostStepItem): StepEvent => ({ kind: "item", item: value });
+const THINKING: readonly StepEvent[] = [item({ kind: "thinking", index: 0, text: "hm" }), item({ kind: "text", index: 1, text: "a" }), item({ kind: "text", index: 1, text: "b" })];
+const STOP = item({ kind: "stop", stopReason: "end_turn", usage: null });
+const ROW: SignedBlock = { type: "thinking", thinking: "hm", signature: "sig" };
+
+/** A step whose events the test hands on one at a time, and the rows that the test writes. */
+function step() {
+  const queue: StepEvent[] = [];
+  let wake = (): void => {};
+  const signed: SignedBlock[] = [];
+  const events: AsyncIterable<StepEvent> = { [Symbol.asyncIterator]: () => ({
+    next: async () => {
+      while (queue.length === 0) await new Promise<void>((resolve) => { wake = resolve; });
+      // SAFETY: the loop above left an event in the queue.
+      return { done: false, value: queue.shift()! };
+    },
+  }) };
+  const rows: AgentRows = { read: () => signed };
+  let progress = 0;
+  let answer: HostedAnswer | undefined;
+  const stream = hostedStreamEvents(events, rows, 0, "model", async () => new Error("service answer"), (value) => { answer = value; }, () => { progress += 1; });
+  return {
+    stream,
+    send: (...sent: readonly StepEvent[]) => { queue.push(...sent); wake(); },
+    write: (block: SignedBlock) => { signed.push(block); },
+    progress: () => progress,
+    answer: () => answer,
+  };
+}
+
+const kinds = (events: readonly Anthropic.RawMessageStreamEvent[]): string[] => events.map((event) => {
+  if (event.type === "content_block_delta") return `${event.index}:${event.delta.type}`;
