+describe("hostedStreamEvents", () => {
+  test("holds back the chunks after a thinking block until the engine writes its row at the response's end", async () => {
+    const hosted = step();
+    hosted.send(...THINKING);
+    const seen: Anthropic.RawMessageStreamEvent[] = [];
