+    await Bun.sleep(80);
+    expect(kinds(seen)).toEqual(["message_start", "0:content_block_start", "0:thinking_delta"]);
+    expect(hosted.progress()).toBe(1);
+    hosted.send(STOP);
+    await Bun.sleep(40);
+    hosted.write(ROW);
+    await drained;
+    expect(kinds(seen)).toEqual([
+      "message_start", "0:content_block_start", "0:thinking_delta", "0:signature_delta", "0:content_block_stop",
+      "1:content_block_start", "1:text_delta", "1:text_delta", "1:content_block_stop", "message_delta", "message_stop",
