+
+const THINKING: SignedBlock = { type: "thinking", thinking: "plan it", signature: "sig" };
+const REDACTED: SignedBlock = { type: "redacted_thinking", data: "opaque" };
+
+describe("hostedStreamEvents", () => {
+  test("a response that writes long after its thinking, whose rows the engine writes only after the stop chunk, streams completely in Anthropic order and reports each held-back chunk as progress", async () => {
+    let written = false;
+    const rows: AgentRows = { read: () => written ? [THINKING, REDACTED] : [] };
+    const texts = Array.from({ length: 50 }, (_, n) => `t${n}`);
+    const items: HostStepItem[] = [
+      { kind: "thinking", index: 0, text: "plan" },
+      ...texts.map((text): HostStepItem => ({ kind: "text", index: 2, text })),
+      { kind: "stop", stopReason: "end_turn", usage: null },
+    ];
+    async function* events(): AsyncGenerator<StepEvent> {
+      for (const item of items) {
+        await Bun.sleep(1);
+        if (item.kind === "stop") setTimeout(() => { written = true; }, 50);
+        yield { kind: "item", item };
+      }
+      yield { kind: "done" };
+    }
+    let progress = 0;
+    let answer: HostedAnswer | undefined;
+    const out: Anthropic.RawMessageStreamEvent[] = [];
+    for await (const event of hostedStreamEvents(events(), rows, 0, "model", async () => new Error("no stop chunk"), (ended) => { answer = ended; }, () => { progress += 1; })) out.push(event);
+
+    expect(out.map((event) => event.type === "content_block_delta" ? `${event.index}:${event.delta.type}` : "index" in event ? `${event.index}:${event.type}` : event.type)).toEqual([
+      "message_start",
+      "0:content_block_start", "0:thinking_delta", "0:thinking_delta", "0:signature_delta", "0:content_block_stop",
+      "1:content_block_start", "1:content_block_stop",
+      "2:content_block_start", ...texts.map(() => "2:text_delta"), "2:content_block_stop",
+      "message_delta", "message_stop",
+    ]);
+    expect(progress).toBeGreaterThanOrEqual(texts.length);
+    expect(answer?.message.content).toEqual([THINKING, REDACTED, { type: "text", text: texts.join("") }]);
+  });
+});

