+import { afterEach, describe, expect, setSystemTime, test } from "bun:test";
+import type Anthropic from "@anthropic-ai/sdk";
+import { Effect, Queue, type Cause } from "effect";
+import { LlmStreamError } from "../../../../../../src/orchestration/agent-runtime/llm/errors.js";
+import type { SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+import { queueIterable } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/queue-iterable.js";
+
+const SIGNED: SignedBlock = { type: "thinking", thinking: "plan", signature: "sig" };
+const STOP = { kind: "stop", stopReason: "end_turn", usage: null } as const;
+const FAILURE = new Error("service answer");
+
+/** A step whose chunks and agent-file rows the test feeds, read by `hostedStreamEvents` as the bridge reads them. */
+function step() {
+  const queue = Effect.runSync(Queue.unbounded<StepEvent, Error | Cause.Done>());
+  const signed: SignedBlock[] = [];
+  let progress = 0;
+  const events: Anthropic.RawMessageStreamEvent[] = [];
+  const stream = hostedStreamEvents(queueIterable(queue), { read: () => signed }, 0, "model", async () => FAILURE, () => {}, () => { progress += 1; });
+  const drained = (async () => {
+    for await (const event of stream) events.push(event);
+  })();
+  return {
+    send: (event: StepEvent) => { Queue.offerUnsafe(queue, event); },
+    writeRow: () => { signed.push(SIGNED); },
+    progress: () => progress,
+    events,
+    drained,
+  };
+}
+
+/** Lets the stream poll the agent file a few times. */
+const polls = () => Bun.sleep(80);
+
+describe("hostedStreamEvents", () => {
+  afterEach(() => { setSystemTime(); });
+
+  test("a response that writes long after its thinking, before the engine writes the thinking row, completes in order", async () => {
+    const run = step();
+    run.send({ kind: "item", item: { kind: "thinking", index: 0, text: "plan" } });
+    for (const text of ["a", "b", "c"]) {
+      run.send({ kind: "item", item: { kind: "text", index: 1, text } });
+      await polls();
+    }
+    // The text after the first chunk that started the wait waits behind the thinking block, each chunk a progress.
+    expect(run.events.some((event) => event.type === "content_block_start" && event.index === 1)).toBe(false);
+    run.send({ kind: "item", item: STOP });
+    await polls();
+    expect(run.progress()).toBe(3);
+    run.writeRow();
+    await run.drained;
+    expect(run.events.map((event) => event.type === "content_block_delta" ? `${event.index}:${event.delta.type}` : `${event.type}${"index" in event ? `:${event.index}` : ""}`)).toEqual([
+      "message_start", "content_block_start:0", "0:thinking_delta", "0:signature_delta", "content_block_stop:0",
+      "content_block_start:1", "1:text_delta", "1:text_delta", "1:text_delta", "content_block_stop:1", "message_delta", "message_stop",
+    ]);
+  });
+
+  test("a thinking row still missing a bound after the stop chunk fails transient", async () => {
+    const run = step();
+    run.send({ kind: "item", item: { kind: "thinking", index: 0, text: "plan" } });
+    run.send({ kind: "item", item: { kind: "text", index: 1, text: "a" } });
+    run.send({ kind: "item", item: STOP });
+    await polls();
+    setSystemTime(new Date(Date.now() + 61_000));
+    const error = await run.drained.then(() => undefined, (thrown: unknown) => thrown);
+    expect(error).toBeInstanceOf(LlmStreamError);
+    expect((error as LlmStreamError).kind).toBe("transient");
+    expect((error as Error).message).toContain("wrote no row");
+  });
+
+  test("a step that ends without a stop chunk while a row is pending fails with the service's answer", async () => {
+    const run = step();
+    run.send({ kind: "item", item: { kind: "thinking", index: 0, text: "plan" } });
+    run.send({ kind: "item", item: { kind: "text", index: 1, text: "a" } });
+    run.send({ kind: "done" });
+    expect(await run.drained.then(() => undefined, (thrown: unknown) => thrown)).toBe(FAILURE);
+  });
+});

