+/** A step's chunks: a thinking block, a redacted thinking block, which yields no chunk, and a text block. */
+const RESPONSE: readonly HostStepItem[] = [
+  { kind: "thinking", index: 0, text: "Let me" },
+  { kind: "thinking", index: 0, text: " think" },
+  { kind: "text", index: 2, text: "Hello" },
+  { kind: "text", index: 2, text: " world" },
