+const SIGNED: readonly SignedBlock[] = [
+  { type: "thinking", thinking: "Let me think.", signature: "sig" },
+  { type: "redacted_thinking", data: "blob" },
+];
+
+/** The step's chunks, as the host gate hands them on. `onStop` runs as the step sends its stop chunk.
+ *  @yields {StepEvent} Each chunk of `items`. */
+async function* stepEvents(items: readonly HostStepItem[], onStop: () => void = () => {}): AsyncGenerator<StepEvent> {
+  for (const item of items) {
+    if (item.kind === "stop") onStop();
+    yield { kind: "item", item };
+  }
