+async function collect(stream: AsyncIterable<Anthropic.RawMessageStreamEvent>): Promise<Anthropic.RawMessageStreamEvent[]> {
+  const events: Anthropic.RawMessageStreamEvent[] = [];
+  for await (const event of stream) events.push(event);
+  return events;
+}
